b() { BOOKINGS=$t bash src/book.sh "$@" >/dev/null 2>&1; }
b aoi 2026-01-05 09:00 10:00 x 4 || { echo "4 people in aoi rejected"; fail=1; }
b aoi 2026-01-05 10:00 11:00 y 5; [ $? = 1 ] || { echo "5 people in aoi should exit 1"; fail=1; }
